pub fn lines(contents: &str, start: usize, end: usize) -> Result<String> {
    if start == 0 || end < start {
        return Err(format!("invalid inclusive line range {start}..{end}"));
    }
    let lines: Vec<_> = contents.split_inclusive('\n').collect();
    if end > lines.len() {
        return Err(format!(
            "line range {start}..{end} exceeds file length {}",
            lines.len()
        ));
    }
    Ok(lines[start - 1..end].concat())
}

pub fn snapshot(root: &Path, path: &str, start: usize, end: usize) -> Result<Input> {
    let root = root.canonicalize().map_err(|e| e.to_string())?;
    let text = read(&root, Path::new(path))?;
    Ok(Input {
        path: path.into(),
        line_start: start,
        line_end: end,
        contents: lines(&text, start, end)?,
    })
}

fn line_ranges_preserve_endings_unicode_and_final_newline() {
    assert_eq!(lines("α\r\nβ\r\nγ", 1, 2).unwrap(), "α\r\nβ\r\n");
    assert_eq!(lines("α\r\nβ\r\nγ", 3, 3).unwrap(), "γ");
    assert_eq!(lines("\n", 1, 1).unwrap(), "\n");
    for (text, start, end) in [
        ("", 1, 1),
        ("a\n", 0, 1),
        ("a\nb", 2, 1),
        ("a\n", 2, 2),
        ("a", 1, usize::MAX),
    ] {
        assert!(lines(text, start, end).is_err());
    }
}

fn schema_requires_fields_and_nonempty_inputs() {
    let f = Fixture::new();
    for field in ["requirement", "inputs", "justification"] {
        let mut evidence = f.evidence();
        evidence.as_object_mut().unwrap().remove(field);
        f.save(&evidence);
        assert!(!f.errors().is_empty());
    }
    let mut evidence = f.evidence();
    evidence["inputs"] = json!([]);
    f.save(&evidence);
    assert!(f.errors()[0].contains("at least one"));
    evidence = f.evidence();
    evidence["extra"] = true.into();
    f.save(&evidence);
    assert!(!f.errors().is_empty());
    for n in [json!(0), json!(-1), json!(1.5), json!(999)] {
        evidence = f.evidence();
        evidence["inputs"][0]["line_start"] = n;
        f.save(&evidence);
        assert!(!f.errors().is_empty());
    }
}
